css:
.cd-preview-wrapper {
  font-family: Arial, sans-serif;
  color: #0f172a;
  font-size: 12px;
}

.cd-card {
  margin: 12px 0 18px 0;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  overflow: hidden;
  background: #ffffff;
  page-break-inside: avoid;
  break-inside: avoid;
}

.cd-header {
  text-align: center;
  padding: 10px 12px 8px 12px;
  border-bottom: 3px solid #1f6e8c;
  background: #ffffff;
}

.cd-title-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
}

.cd-title-en {
  flex: 1;
  text-align: left;
  font-size: 20px;
  font-weight: 900;
  color: #0c4a6e;
  line-height: 1.25;
}

.cd-title-ar {
  flex: 1;
  text-align: right;
  font-size: 18px;
  font-weight: 900;
  color: #0c4a6e;
  direction: rtl;
  line-height: 1.25;
}

.cd-info-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 10px 10px 8px 10px;
}

.cd-badge {
  background: #f1f5f9;
  border-radius: 999px;
  padding: 5px 14px;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.cd-badge strong {
  color: #1f6e8c;
  font-weight: 900;
}

.cd-badge-warning {
  background: #fff7ed;
  border-color: #fed7aa;
  color: #9a3412;
}

.cd-badge-danger {
  background: #fef2f2;
  border-color: #fecaca;
  color: #991b1b;
}

.cd-badge-success {
  background: #f0fdf4;
  border-color: #bbf7d0;
  color: #166534;
}

.cd-rtl {
  direction: rtl;
}

.cd-operation-header {
  padding: 9px 12px 8px 12px;
  border-bottom: 2px solid #e6f7ff;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
}

.cd-operation-title-en {
  font-size: 14px;
  font-weight: 900;
  color: #1f6e8c;
}

.cd-operation-title-ar {
  font-size: 13px;
  font-weight: 900;
  direction: rtl;
  color: #2c3e50;
}

.cd-table {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
  font-size: 12px;
}

.cd-table th {
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  padding: 7px 6px;
  text-align: center;
  font-weight: 900;
  color: #111827;
  line-height: 1.25;
}

.cd-table td {
  border: 1px solid #e2e8f0;
  padding: 7px 6px;
  text-align: center;
  vertical-align: middle;
  line-height: 1.3;
}

.cd-table .item-col {
  text-align: left;
  font-weight: 800;
  color: #0f172a;
  width: 35%;
}

.cd-number {
  font-weight: 900;
  color: #0f172a;
}

.cd-uom-small {
  font-size: 9.5px;
  font-weight: 800;
  color: #475569;
  margin-left: 3px;
}

.cd-small {
  font-size: 10.5px;
  color: #64748b;
  font-weight: 700;
  margin-top: 2px;
}

.item-name-ar {
  direction: rtl;
  text-align: right;
  font-weight: 800;
  color: #334155;
  margin-top: 3px;
  font-size: 11px;
}

.bi-head {
  line-height: 1.25;
}

.bi-head .en {
  font-weight: 900;
  font-size: 11px;
}

.bi-head .ar {
  font-weight: 800;
  font-size: 11px;
  direction: rtl;
  color: #334155;
  margin-top: 2px;
}

.cd-muted {
  color: #64748b;
  font-weight: 800;
}

.cd-danger {
  color: #b91c1c;
  font-weight: 900;
}

.cd-warning {
  color: #9a3412;
  font-weight: 900;
}

.cd-success {
  color: #166534;
  font-weight: 900;
}

.cd-icon-up {
  display: inline-block;
  color: #15803d;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-icon-down {
  display: inline-block;
  color: #b91c1c;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-icon-ok {
  display: inline-block;
  color: #166534;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-diff-up {
  color: #15803d;
  font-weight: 900;
}

.cd-diff-down {
  color: #b91c1c;
  font-weight: 900;
}

.cd-diff-ok {
  color: #166534;
  font-weight: 900;
}

.cd-notes-block {
  margin: 8px 10px 10px 10px;
  padding: 0;
  border: 0;
  background: transparent;
  page-break-inside: avoid;
}

.cd-notes-title {
  font-size: 11px;
  font-weight: 900;
  color: #0c4a6e;
  margin-bottom: 4px;
}

.cd-note-line {
  display: block;
  padding: 2px 0;
  border: 0;
  background: transparent;
  font-size: 11px;
  line-height: 1.45;
  color: #334155;
  font-weight: 700;
  white-space: pre-wrap;
}

.cd-calc-block {
  margin: 8px 10px 10px 10px;
  padding: 8px 10px;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  background: #f8fafc;
  page-break-inside: avoid;
  break-inside: avoid;
}

.cd-dish-options-block {
  margin-top: 10px;
  background: #ffffff;
}

.cd-calc-title {
  font-size: 12px;
  font-weight: 900;
  color: #0c4a6e;
  margin-bottom: 8px;
}

.cd-calc-section {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px dashed #cbd5e1;
}

.cd-calc-section:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.cd-calc-section-title {
  font-size: 11px;
  font-weight: 900;
  color: #1f6e8c;
  margin-bottom: 4px;
}

.cd-calc-line {
  font-size: 10.5px;
  line-height: 1.45;
  color: #0f172a;
  margin: 2px 0;
}

.cd-calc-material {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px solid #e2e8f0;
}

.cd-calc-material:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.cd-receiving-box {
  margin-top: 6px;
  padding: 6px 7px;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  background: #ffffff;
}

.cd-impact-title {
  margin-top: 8px;
  margin-bottom: 4px;
  font-size: 10.8px;
  font-weight: 900;
  color: #334155;
}

.cd-mini-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 5px;
  margin-bottom: 8px;
  font-size: 10.5px;
}

.cd-mini-table th {
  border: 1px solid #cbd5e1;
  background: #f1f5f9;
  padding: 5px;
  font-weight: 900;
  text-align: center;
}

.cd-mini-table td {
  border: 1px solid #e2e8f0;
  padding: 5px;
  text-align: center;
  vertical-align: middle;
}

.cd-output-table {
  margin-top: 10px;
}

.cd-output-number {
  font-size: 16px;
  font-weight: 900;
  color: #0f172a;
}

.cd-output-uom {
  font-size: 11px;
  font-weight: 800;
  color: #334155;
}

.cd-coverage-warning {
  font-size: 12px;
  font-weight: 900;
  color: #9a3412;
}

.cd-coverage-danger {
  font-size: 12px;
  font-weight: 900;
  color: #b91c1c;
}

.cd-coverage-success {
  font-size: 12px;
  font-weight: 900;
  color: #166534;
}

@media print {
  .cd-card,
  .cd-calc-block,
  .cd-notes-block,
  .cd-receiving-box {
    page-break-inside: avoid;
    break-inside: avoid;
  }

  .cd-header,
  .cd-badge,
  .cd-operation-header,
  .cd-table th,
  .cd-mini-table th,
  .cd-calc-block {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}

html:
{# ============================================================
   Print Format Name: Catering Dish Calculation
   DocType: Catering Dish
   HTML / Jinja
   ============================================================ #}

{% set person_qty = frappe.utils.flt(doc.test_person_qty or 100) %}
{% set buffet_qty = frappe.utils.flt(doc.default_buffet_qty or 1) %}
{% set method = doc.output_planning_method or "Manual" %}
{% set basis_qty = frappe.utils.flt(doc.recipe_basis_qty or 0) %}
{% set basis_uom = doc.default_uom or "" %}
{% set output_uom = doc.output_container_uom or "Output" %}
{% set output_rounding = doc.output_rounding_method or "Round Up" %}
{% set receiving_display_method = doc.receiving_display_method or "Required Qty" %}
{% set show_qty_difference = frappe.utils.cint(doc.show_output_qty_difference or 0) %}
{% set workstation_method = doc.workstation_calculation_method or "" %}
{% set workstation_load_qty = frappe.utils.flt(doc.workstation_load_qty or 0) %}
{% set workstation_load_uom = doc.workstation_load_uom or "" %}

{% macro fmt(value) %}
  {% set v = frappe.utils.flt(value or 0) %}
  {% if v == (v|int) %}
    {{ "{:,}".format(v|int) }}
  {% else %}
    {{ "{:,.3f}".format(v).rstrip("0").rstrip(".") }}
  {% endif %}
{% endmacro %}

{% macro round_text(method) %}
  {% if method == "Round Down" %}
    Round Down
  {% elif method == "Half Round" %}
    Half Round
  {% elif method == "No Rounding" %}
    No Rounding
  {% else %}
    Round Up
  {% endif %}
{% endmacro %}

{% macro yes_no(value) %}
  {% if frappe.utils.cint(value or 0) %}
    Yes
  {% else %}
    No
  {% endif %}
{% endmacro %}

{% macro diff_icon(diff, uom) %}
  {% if frappe.utils.flt(diff or 0) > 0 %}
    <span class="cd-icon-up">▲</span>
    <span class="cd-diff-up">{{ fmt(diff) }} {{ uom }}</span>
  {% elif frappe.utils.flt(diff or 0) < 0 %}
    <span class="cd-icon-down">▼</span>
    <span class="cd-diff-down">{{ fmt((diff or 0) * -1) }} {{ uom }}</span>
  {% else %}
    <span class="cd-icon-ok">✓</span>
    <span class="cd-diff-ok">Exact</span>
  {% endif %}
{% endmacro %}

{% macro uom_short(uom) %}
  {% if (uom or "") == "Litre" %}
    L
  {% else %}
    {{ uom or "" }}
  {% endif %}
{% endmacro %}

{% macro receiving_uom(row) %}
  {% set mode = row.receiving_mode or "Single Unit" %}
  {% if mode == "Unit Breakdown" %}
    {% if row.large_pack_uom and row.small_pack_uom %}
      {{ row.large_pack_uom }} / {{ row.small_pack_uom }}
    {% else %}
      {{ row.receiving_capacity_uom or row.uom or "" }}
    {% endif %}
  {% else %}
    {{ row.receiving_capacity_uom or row.uom or "" }}
  {% endif %}
{% endmacro %}

{% macro receiving_value(row, required_qty) %}
  {% set mode = row.receiving_mode or "Single Unit" %}
  {% set rounding = row.receiving_rounding_method or "Round Up" %}

  {% if mode == "No Receiving" %}
    -
  {% elif mode == "Unit Breakdown" %}
    {% set large_qty = frappe.utils.flt(row.large_pack_qty or 0) %}
    {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}

    {% if large_qty > 0 and small_qty > 0 %}
      {% set large_count = (required_qty / large_qty)|int %}
      {% set remaining = required_qty - (large_count * large_qty) %}

      {% if remaining < 0 %}
        {% set remaining = 0 %}
      {% endif %}

      {% set small_raw = remaining / small_qty %}
      {% set small_int = small_raw|int %}
      {% set small_decimal = small_raw - small_int %}

      {% if rounding == "No Rounding" %}
        {% set small_count = small_raw %}
      {% elif rounding == "Round Down" %}
        {% set small_count = small_int %}
      {% elif rounding == "Half Round" %}
        {% if small_decimal >= 0.5 %}
          {% set small_count = small_int + 1 %}
        {% else %}
          {% set small_count = small_int %}
        {% endif %}
      {% else %}
        {% if small_raw > small_int %}
          {% set small_count = small_int + 1 %}
        {% else %}
          {% set small_count = small_int %}
        {% endif %}
      {% endif %}

      {% if large_count > 0 %}
        {{ fmt(large_count) }} {{ row.large_pack_uom }}
      {% endif %}

      {% if large_count > 0 and small_count > 0 %}
        +
      {% endif %}

      {% if small_count > 0 %}
        {{ fmt(small_count) }} {{ row.small_pack_uom }}
      {% endif %}

      {% if large_count <= 0 and small_count <= 0 %}
        0 {{ row.small_pack_uom }}
      {% endif %}
    {% else %}
      -
    {% endif %}
  {% else %}
    {% set cap = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
    {% if cap > 0 %}
      {% set raw = required_qty / cap %}
      {% set raw_int = raw|int %}
      {% set raw_decimal = raw - raw_int %}

      {% if rounding == "No Rounding" %}
        {% set qty = raw %}
      {% elif rounding == "Round Down" %}
        {% set qty = raw_int %}
      {% elif rounding == "Half Round" %}
        {% if raw_decimal >= 0.5 %}
          {% set qty = raw_int + 1 %}
        {% else %}
          {% set qty = raw_int %}
        {% endif %}
      {% else %}
        {% if raw > raw_int %}
          {% set qty = raw_int + 1 %}
        {% else %}
          {% set qty = raw_int %}
        {% endif %}
      {% endif %}

      {% if qty <= 0 and required_qty > 0 %}
        {% set qty = 1 %}
      {% endif %}

      {{ fmt(qty) }}
    {% else %}
      -
    {% endif %}
  {% endif %}
{% endmacro %}

{# ============================================================
   Output Calculation
   ============================================================ #}

{% set output_ns = namespace(
  can=true,
  message="",
  required_qty=0,
  required_uom="",
  capacity_qty=0,
  capacity_uom="",
  output_raw=0,
  output_qty=0,
  actual_qty=0,
  extra_qty=0,
  shortage_qty=0,
  full_output_qty=0,
  remaining_qty=0,
  driver_item="",
  driver_qty_for_basis=0,
  driver_qty_per_person=0,
  driver_qty_per_output=0
) %}

{% if method == "Manual" %}
  {% set output_ns.can = false %}
  {% set output_ns.message = "Manual output planning." %}

{% elif method == "Per Buffet" %}
  {% set output_ns.required_qty = buffet_qty %}
  {% set output_ns.required_uom = output_uom %}
  {% set output_ns.capacity_qty = 1 %}
  {% set output_ns.capacity_uom = output_uom %}
  {% set output_ns.output_raw = buffet_qty %}

{% elif method == "Covers Persons" %}
  {% if basis_qty > 0 and basis_uom == "Person" %}
    {% set output_ns.required_qty = person_qty %}
    {% set output_ns.required_uom = "Person" %}
    {% set output_ns.capacity_qty = basis_qty %}
    {% set output_ns.capacity_uom = "Person" %}
    {% set output_ns.output_raw = person_qty / basis_qty %}
  {% else %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Covers Persons requires Recipe Basis Qty > 0 and UOM = Person." %}
  {% endif %}

{% elif method == "Dish Qty Per Person" %}
  {% set cap_qty = frappe.utils.flt(doc.output_container_capacity_qty or 0) %}
  {% set cap_uom = doc.output_container_capacity_uom or "" %}

  {% if basis_qty > 0 and basis_uom and cap_qty > 0 and cap_uom %}
    {% set output_ns.required_qty = person_qty * basis_qty %}
    {% set output_ns.required_uom = basis_uom %}
    {% set output_ns.capacity_qty = cap_qty %}
    {% set output_ns.capacity_uom = cap_uom %}
    {% set output_ns.output_raw = output_ns.required_qty / cap_qty %}
  {% else %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Dish Qty Per Person requires Recipe Basis and Output Container Capacity." %}
  {% endif %}

{% elif method == "Output Driver Material" %}
  {% set driver_ns = namespace(found=false, item="", qty_basis=0, qty_person=0, qty_output=0, uom="") %}

  {% for row in doc.materials or [] %}
    {% if row.material__calculation_base == "Output Driver" and not driver_ns.found %}
      {% set driver_ns.found = true %}
      {% set driver_ns.item = row.material_item %}
      {% set driver_ns.qty_basis = frappe.utils.flt(row.qty_per_person or 0) %}
      {% set driver_ns.qty_person = frappe.utils.flt(row.qty_per_person or 0) * frappe.utils.flt(basis_qty or 1) %}
      {% set driver_ns.qty_output = frappe.utils.flt(row.qty_per_output or 0) %}
      {% set driver_ns.uom = row.uom or "" %}
    {% endif %}
  {% endfor %}

  {% if driver_ns.found and driver_ns.qty_person > 0 and driver_ns.qty_output > 0 %}
    {% set output_ns.driver_item = driver_ns.item %}
    {% set output_ns.driver_qty_for_basis = driver_ns.qty_basis %}
    {% set output_ns.driver_qty_per_person = driver_ns.qty_person %}
    {% set output_ns.driver_qty_per_output = driver_ns.qty_output %}
    {% set output_ns.required_qty = person_qty * driver_ns.qty_person %}
    {% set output_ns.required_uom = driver_ns.uom %}
    {% set output_ns.capacity_qty = driver_ns.qty_output %}
    {% set output_ns.capacity_uom = driver_ns.uom %}
    {% set output_ns.output_raw = output_ns.required_qty / output_ns.capacity_qty %}
  {% else %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Output Driver Material requires one Output Driver material with Qty For Recipe Basis and Qty Per Output." %}
  {% endif %}

{% elif method == "Sum Output Materials" %}
  {% set sum_ns = namespace(qty=0, uom="", has_rows=false, mismatch=false) %}

  {% for row in doc.materials or [] %}
    {% if row.material_item and frappe.utils.cint(row.include_in_output_qty or 0) %}
      {% set sum_ns.has_rows = true %}

      {% if not sum_ns.uom %}
        {% set sum_ns.uom = row.uom or "" %}
      {% elif sum_ns.uom != (row.uom or "") %}
        {% set sum_ns.mismatch = true %}
      {% endif %}

      {% set base = row.material__calculation_base or "Per Person" %}

      {% if base == "Per Person" or base == "Output Driver" %}
        {% set row_qty = frappe.utils.flt(row.qty_per_person or 0) * basis_qty * person_qty %}
      {% else %}
        {% set row_qty = 0 %}
      {% endif %}

      {% set sum_ns.qty = sum_ns.qty + row_qty %}
    {% endif %}
  {% endfor %}

  {% set cap_qty = frappe.utils.flt(doc.output_container_capacity_qty or 0) %}
  {% set cap_uom = doc.output_container_capacity_uom or "" %}

  {% if not sum_ns.has_rows %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "No materials are marked Include in Output Qty." %}
  {% elif sum_ns.mismatch %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Cannot sum output materials with different UOM." %}
  {% elif cap_qty <= 0 or not cap_uom %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Sum Output Materials requires Output Container Capacity Qty and UOM." %}
  {% else %}
    {% set output_ns.required_qty = sum_ns.qty %}
    {% set output_ns.required_uom = sum_ns.uom %}
    {% set output_ns.capacity_qty = cap_qty %}
    {% set output_ns.capacity_uom = cap_uom %}
    {% set output_ns.output_raw = output_ns.required_qty / cap_qty %}
  {% endif %}
{% endif %}

{# Apply Output Rounding #}

{% if output_ns.can %}
  {% set raw = output_ns.output_raw %}
  {% set raw_int = raw|int %}
  {% set raw_decimal = raw - raw_int %}

  {% if output_rounding == "No Rounding" %}
    {% set output_ns.output_qty = raw %}
  {% elif output_rounding == "Round Down" %}
    {% set output_ns.output_qty = raw_int %}
  {% elif output_rounding == "Half Round" %}
    {% if raw_decimal >= 0.5 %}
      {% set output_ns.output_qty = raw_int + 1 %}
    {% else %}
      {% set output_ns.output_qty = raw_int %}
    {% endif %}
  {% else %}
    {% if raw > raw_int %}
      {% set output_ns.output_qty = raw_int + 1 %}
    {% else %}
      {% set output_ns.output_qty = raw_int %}
    {% endif %}
  {% endif %}

  {% set output_ns.actual_qty = output_ns.output_qty * output_ns.capacity_qty %}
  {% set output_ns.full_output_qty = output_ns.output_raw|int %}
  {% set output_ns.remaining_qty = output_ns.required_qty - (output_ns.full_output_qty * output_ns.capacity_qty) %}

  {% if output_ns.actual_qty > output_ns.required_qty %}
    {% set output_ns.extra_qty = output_ns.actual_qty - output_ns.required_qty %}
  {% elif output_ns.actual_qty < output_ns.required_qty %}
    {% set output_ns.shortage_qty = output_ns.required_qty - output_ns.actual_qty %}
  {% endif %}
{% endif %}

{# Qty Difference #}

{% set qty_diff_ns = namespace(enabled=false, status="", diff=0) %}

{% if show_qty_difference and output_ns.can %}
  {% if output_ns.extra_qty > 0 %}
    {% set qty_diff_ns.enabled = true %}
    {% set qty_diff_ns.status = "Extra" %}
    {% set qty_diff_ns.diff = output_ns.extra_qty %}
  {% elif output_ns.shortage_qty > 0 %}
    {% set qty_diff_ns.enabled = true %}
    {% set qty_diff_ns.status = "Shortage" %}
    {% set qty_diff_ns.diff = output_ns.shortage_qty %}
  {% else %}
    {% set qty_diff_ns.enabled = true %}
    {% set qty_diff_ns.status = "Exact" %}
    {% set qty_diff_ns.diff = 0 %}
  {% endif %}
{% endif %}

{# Runs #}

{% set run_ns = namespace(can=false, raw=0, qty=0, formula="", base_qty=0, base_label="") %}

{% if output_ns.can and workstation_load_qty > 0 %}
  {% set run_ns.can = true %}

  {% if workstation_method == "Output Unit Load" or workstation_method == "Receiving Unit Load" %}
    {% set run_ns.base_qty = output_ns.output_qty %}
    {% set run_ns.base_label = "Output Qty" %}
    {% set run_ns.raw = output_ns.output_qty / workstation_load_qty %}
    {% set run_ns.formula = "Output Qty ÷ Run Load Qty" %}
  {% else %}
    {% set run_ns.base_qty = output_ns.required_qty %}
    {% set run_ns.base_label = "Required Qty" %}
    {% set run_ns.raw = output_ns.required_qty / workstation_load_qty %}
    {% set run_ns.formula = "Required Qty ÷ Run Load Qty" %}
  {% endif %}

  {% set run_int = run_ns.raw|int %}

  {% if run_ns.raw > run_int %}
    {% set run_ns.qty = run_int + 1 %}
  {% else %}
    {% set run_ns.qty = run_int %}
  {% endif %}

  {% if run_ns.qty <= 0 and output_ns.output_qty > 0 %}
    {% set run_ns.qty = 1 %}
  {% endif %}
{% endif %}

<div class="cd-preview-wrapper">
  <div class="cd-card">

    <header class="cd-header">
      <div class="cd-title-row">
        <div class="cd-title-en">Catering Dish Calculation</div>
        <div class="cd-title-ar">نموذج حساب صنف التموين</div>
      </div>
    </header>

    <div class="cd-info-row">
      <span class="cd-badge"><strong>Dish:</strong> {{ doc.dish_name }}</span>

      {% if doc.dish_name_arabic %}
        <span class="cd-badge cd-rtl"><strong>الصنف:</strong> {{ doc.dish_name_arabic }}</span>
      {% endif %}

      {% if doc.item_code %}
        <span class="cd-badge"><strong>Item:</strong> {{ doc.item_code }}</span>
      {% endif %}

      <span class="cd-badge"><strong>Person Qty:</strong> {{ fmt(person_qty) }}</span>

      {% if method == "Per Buffet" %}
        <span class="cd-badge"><strong>Buffet Qty:</strong> {{ fmt(buffet_qty) }}</span>
      {% endif %}

      <span class="cd-badge"><strong>Planning:</strong> {{ method }}</span>

      {% if doc.default_workstation %}
        <span class="cd-badge"><strong>Equipment:</strong> {{ doc.default_workstation }}</span>
      {% endif %}

      {% if qty_diff_ns.enabled %}
        {% if qty_diff_ns.status == "Extra" %}
          <span class="cd-badge cd-badge-warning">
            <span class="cd-icon-up">▲</span>
            <strong>{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</strong>
          </span>
        {% elif qty_diff_ns.status == "Shortage" %}
          <span class="cd-badge cd-badge-danger">
            <span class="cd-icon-down">▼</span>
            <strong>{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</strong>
          </span>
        {% else %}
          <span class="cd-badge cd-badge-success">
            <span class="cd-icon-ok">✓</span>
            <strong>Exact</strong>
          </span>
        {% endif %}
      {% endif %}
    </div>

    <div class="cd-operation-header">
      <span class="cd-operation-title-en">Calculation Preview</span>
      <span class="cd-operation-title-ar">معاينة الحساب</span>
    </div>

    <table class="cd-table">
      <thead>
        <tr>
          <th>
            <div class="bi-head">
              <div class="en">Item Name</div>
              <div class="ar">اسم الصنف</div>
            </div>
          </th>
          <th>
            <div class="bi-head">
              <div class="en">Receiving</div>
              <div class="ar">الاستلام</div>
            </div>
          </th>
          <th>
            <div class="bi-head">
              <div class="en">UOM</div>
              <div class="ar">الوحدة</div>
            </div>
          </th>
          <th>
            <div class="bi-head">
              <div class="en">Output / Batch</div>
              <div class="ar">المخرج / الدفعة</div>
            </div>
          </th>
          <th>
            <div class="bi-head">
              <div class="en">Runs</div>
              <div class="ar">مرات التشغيل</div>
            </div>
          </th>
        </tr>
      </thead>

      <tbody>
        {% if doc.materials %}
          {% for row in doc.materials %}
            {% if row.material_item %}
              {% set material_base = row.material__calculation_base or "Per Person" %}
              {% set receiving_applicable = frappe.utils.cint(row.include_in_purchase or 0) and (row.receiving_mode or "Single Unit") != "No Receiving" %}
              {% set batch_applicable = frappe.utils.cint(row.include_in_production or 0) %}

              {% if material_base == "Per Output" %}
                {% set required_qty = frappe.utils.flt(row.qty_per_output or 0) * output_ns.output_qty %}
                {% set batch_qty = frappe.utils.flt(row.qty_per_output or 0) %}
              {% elif material_base == "Output Driver" %}
                {% set required_qty = frappe.utils.flt(row.qty_per_output or 0) * output_ns.output_qty %}
                {% set batch_qty = frappe.utils.flt(row.qty_per_output or 0) %}
              {% elif material_base == "Per Person" %}
                {% set qty_per_person = frappe.utils.flt(row.qty_per_person or 0) * basis_qty %}
                {% set required_qty = qty_per_person * person_qty %}

                {% if run_ns.qty > 0 %}
                  {% set batch_qty = required_qty / run_ns.qty %}
                {% else %}
                  {% set batch_qty = required_qty %}
                {% endif %}
              {% else %}
                {% set required_qty = 0 %}
                {% set batch_qty = 0 %}
              {% endif %}

              {% set item_name = frappe.db.get_value("Item", row.material_item, "item_name") or "" %}
              {% set item_name_ar = frappe.db.get_value("Item", row.material_item, "item_name_arabic") or "" %}

              <tr>
                <td class="item-col">
                  <div>{{ item_name or row.material_item }}</div>

                  {% if item_name_ar %}
                    <div class="item-name-ar">{{ item_name_ar }}</div>
                  {% endif %}

                  <div class="cd-small">{{ row.material_item }}</div>
                  <div class="cd-small">Base: {{ material_base }}</div>
                </td>

                <td>
                  <span class="cd-number">
                    {% if receiving_applicable %}
                      {{ receiving_value(row, required_qty) }}
                    {% else %}
                      -
                    {% endif %}
                  </span>
                </td>

                <td>
                  {% if receiving_applicable %}
                    {{ receiving_uom(row) }}
                  {% elif batch_applicable %}
                    {{ row.uom or "" }}
                  {% else %}
                    -
                  {% endif %}
                </td>

                <td>
                  <span class="cd-number">
                    {% if batch_applicable %}
                      {% if material_base == "Per Output" or material_base == "Output Driver" %}
                        {{ fmt(row.qty_per_output) }}
                        <span class="cd-uom-small">{{ uom_short(row.uom) }}</span>
                      {% elif receiving_applicable %}
                        {{ receiving_value(row, batch_qty) }}
                        <span class="cd-uom-small">{{ receiving_uom(row) }}</span>
                      {% else %}
                        {{ fmt(batch_qty) }}
                        <span class="cd-uom-small">{{ uom_short(row.uom) }}</span>
                      {% endif %}
                    {% else %}
                      -
                    {% endif %}
                  </span>
                </td>

                <td>
                  <span class="cd-number">
                    {% if batch_applicable and run_ns.can %}
                      {{ fmt(run_ns.qty) }}
                    {% else %}
                      -
                    {% endif %}
                  </span>
                </td>
              </tr>
            {% endif %}
          {% endfor %}

        {% else %}
          <tr>
            <td class="item-col">
              <div>{{ doc.item_name or doc.dish_name }}</div>

              {% if doc.item_name_arabic or doc.dish_name_arabic %}
                <div class="item-name-ar">{{ doc.item_name_arabic or doc.dish_name_arabic }}</div>
              {% endif %}

              {% if doc.item_code %}
                <div class="cd-small">{{ doc.item_code }}</div>
              {% endif %}
            </td>

            <td>
              <span class="cd-number">
                {% if output_ns.can %}
                  {% if receiving_display_method == "No Receiving" %}
                    -
                  {% elif receiving_display_method == "Output Qty" %}
                    {{ fmt(output_ns.output_qty) }}
                  {% else %}
                    {{ fmt(output_ns.required_qty) }}
                  {% endif %}
                {% else %}
                  -
                {% endif %}
              </span>
            </td>

            <td>
              {% if output_ns.can %}
                {% if receiving_display_method == "No Receiving" %}
                  -
                {% elif receiving_display_method == "Output Qty" %}
                  {{ output_uom }}
                {% else %}
                  {{ output_ns.required_uom }}
                {% endif %}
              {% else %}
                -
              {% endif %}
            </td>

            <td>
              <span class="cd-number">
                {% if output_ns.can %}
                  {{ fmt(output_ns.output_qty) }}
                  <span class="cd-uom-small">{{ output_uom }}</span>
                {% else %}
                  -
                {% endif %}
              </span>
            </td>

            <td>
              <span class="cd-number">
                {% if run_ns.can %}
                  {{ fmt(run_ns.qty) }}
                {% else %}
                  -
                {% endif %}
              </span>
            </td>
          </tr>
        {% endif %}
      </tbody>
    </table>

    {% if doc.cooking_instructions %}
      <div class="cd-notes-block">
        <div class="cd-notes-title">Notes / ملاحظات</div>
        <div class="cd-note-line">{{ doc.cooking_instructions }}</div>
      </div>
    {% endif %}

    <div class="cd-calc-block">
      <div class="cd-calc-title">Calculation Breakdown / شرح طريقة الحساب</div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">1) Main Setup / الإعدادات الأساسية</div>
        <div class="cd-calc-line">Output Planning Method = <strong>{{ method }}</strong></div>
        <div class="cd-calc-line">Recipe Basis = <strong>{{ fmt(basis_qty) }} {{ basis_uom }}</strong></div>

        {% if method == "Per Buffet" %}
          <div class="cd-calc-line">Buffet Qty = <strong>{{ fmt(buffet_qty) }}</strong></div>
        {% endif %}

        <div class="cd-calc-line">Output Container = <strong>{{ output_uom }}</strong></div>
        <div class="cd-calc-line">Output Rounding Method = <strong>{{ round_text(output_rounding) }}</strong></div>
        <div class="cd-calc-line">Receiving Display Method = <strong>{{ receiving_display_method }}</strong></div>
        <div class="cd-calc-line">Show Output Qty Difference = <strong>{{ yes_no(doc.show_output_qty_difference) }}</strong></div>
      </div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">2) Required Qty / الكمية المطلوبة</div>

        {% if output_ns.can %}
          {% if method == "Dish Qty Per Person" %}
            <div class="cd-calc-line">
              Required Qty =
              Person Qty × Qty Per Person =
              {{ fmt(person_qty) }}
              ×
              {{ fmt(basis_qty) }}
              =
              <strong>{{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}</strong>
            </div>

          {% elif method == "Covers Persons" %}
            <div class="cd-calc-line">
              Required Qty =
              Person Qty =
              <strong>{{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}</strong>
            </div>

          {% elif method == "Per Buffet" %}
            <div class="cd-calc-line">
              Required Qty =
              Buffet Qty =
              <strong>{{ fmt(buffet_qty) }} {{ output_uom }}</strong>
            </div>

            <div class="cd-calc-line">
              Output Qty =
              Buffet Qty =
              {{ fmt(buffet_qty) }}
              =
              <strong>{{ fmt(output_ns.output_qty) }} {{ output_uom }}</strong>
            </div>

          {% elif method == "Output Driver Material" %}
            <div class="cd-calc-line">
              Driver Material =
              <strong>{{ output_ns.driver_item }}</strong>
            </div>

            <div class="cd-calc-line">
              Driver Qty Per Person =
              Qty For Recipe Basis × Recipe Basis Qty =
              {{ fmt(output_ns.driver_qty_for_basis) }}
              ×
              {{ fmt(basis_qty or 1) }}
              =
              <strong>{{ fmt(output_ns.driver_qty_per_person) }} {{ output_ns.required_uom }}</strong>
            </div>

            <div class="cd-calc-line">
              Required Qty =
              Person Qty × Driver Qty Per Person =
              {{ fmt(person_qty) }}
              ×
              {{ fmt(output_ns.driver_qty_per_person) }}
              =
              <strong>{{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}</strong>
            </div>

          {% else %}
            <div class="cd-calc-line">
              Required Qty =
              <strong>{{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}</strong>
            </div>
          {% endif %}

          {% if method != "Per Buffet" %}
            <div class="cd-calc-line">
              Output Before Rounding =
              {% if output_ns.remaining_qty > 0 %}
                {{ fmt(output_ns.full_output_qty) }} {{ output_uom }} full
                +
                {{ fmt(output_ns.remaining_qty) }} {{ output_ns.required_uom }} remaining
              {% else %}
                {{ fmt(output_ns.full_output_qty) }} {{ output_uom }} full
              {% endif %}
            </div>

            {% if output_ns.remaining_qty > 0 %}
              <div class="cd-calc-line">
                Remaining Qty =
                Required Qty - (Full Output Qty × Capacity Qty)
                =
                {{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}
                -
                (
                {{ fmt(output_ns.full_output_qty) }}
                ×
                {{ fmt(output_ns.capacity_qty) }} {{ output_ns.capacity_uom }}
                )
                =
                <strong>{{ fmt(output_ns.remaining_qty) }} {{ output_ns.required_uom }}</strong>
              </div>
            {% endif %}
          {% endif %}
        {% else %}
          <div class="cd-calc-line cd-danger">{{ output_ns.message }}</div>
        {% endif %}
      </div>

      {% if doc.materials %}
        <div class="cd-calc-section">
          <div class="cd-calc-section-title">3) Materials and Receiving / المواد والاستلام</div>

          {% for row in doc.materials or [] %}
            {% if row.material_item %}
              {% set material_base = row.material__calculation_base or "Per Person" %}
              {% set receiving_applicable = frappe.utils.cint(row.include_in_purchase or 0) and (row.receiving_mode or "Single Unit") != "No Receiving" %}

              {% if material_base == "Per Output" %}
                {% set material_qty_per_person = 0 %}
                {% set required_qty = frappe.utils.flt(row.qty_per_output or 0) * output_ns.output_qty %}
              {% elif material_base == "Output Driver" %}
                {% set material_qty_per_person = frappe.utils.flt(row.qty_per_person or 0) * basis_qty %}
                {% set required_qty = frappe.utils.flt(row.qty_per_output or 0) * output_ns.output_qty %}
              {% elif material_base == "Per Person" %}
                {% set material_qty_per_person = frappe.utils.flt(row.qty_per_person or 0) * basis_qty %}
                {% set required_qty = material_qty_per_person * person_qty %}
              {% else %}
                {% set material_qty_per_person = 0 %}
                {% set required_qty = 0 %}
              {% endif %}

              <div class="cd-calc-material">
                <div class="cd-calc-line">
                  <strong>{{ row.material_item }}</strong>
                  |
                  Material Calculation Base =
                  <strong>{{ material_base }}</strong>
                </div>

                {% if material_base == "Per Person" %}
                  <div class="cd-calc-line">
                    Qty Per Person =
                    Qty For Recipe Basis × Recipe Basis Qty =
                    {{ fmt(row.qty_per_person) }}
                    ×
                    {{ fmt(basis_qty) }}
                    =
                    <strong>{{ fmt(material_qty_per_person) }} {{ row.uom }}</strong>
                  </div>

                  <div class="cd-calc-line">
                    Required Qty =
                    Qty Per Person × Person Qty =
                    {{ fmt(material_qty_per_person) }}
                    ×
                    {{ fmt(person_qty) }}
                    =
                    <strong>{{ fmt(required_qty) }} {{ row.uom }}</strong>
                  </div>

                {% elif material_base == "Per Output" %}
                  <div class="cd-calc-line">
                    Qty Per Output =
                    <strong>{{ fmt(row.qty_per_output) }} {{ row.uom }} per {{ output_uom }}</strong>
                  </div>

                  <div class="cd-calc-line">
                    Required Qty =
                    Qty Per Output × Output Qty =
                    {{ fmt(row.qty_per_output) }}
                    ×
                    {{ fmt(output_ns.output_qty) }}
                    =
                    <strong>{{ fmt(required_qty) }} {{ row.uom }}</strong>
                  </div>

                {% elif material_base == "Output Driver" %}
                  <div class="cd-calc-line">
                    Qty Per Person =
                    Qty For Recipe Basis × Recipe Basis Qty =
                    {{ fmt(row.qty_per_person) }}
                    ×
                    {{ fmt(basis_qty) }}
                    =
                    <strong>{{ fmt(material_qty_per_person) }} {{ row.uom }}</strong>
                  </div>

                  <div class="cd-calc-line">
                    Qty Per Output =
                    <strong>{{ fmt(row.qty_per_output) }} {{ row.uom }} per {{ output_uom }}</strong>
                  </div>

                  <div class="cd-calc-line">
                    Required Qty =
                    Qty Per Output × Output Qty =
                    {{ fmt(row.qty_per_output) }}
                    ×
                    {{ fmt(output_ns.output_qty) }}
                    =
                    <strong>{{ fmt(required_qty) }} {{ row.uom }}</strong>
                  </div>
                {% else %}
                  <div class="cd-calc-line">
                    Required Qty =
                    <strong>Manual / No automatic calculation</strong>
                  </div>
                {% endif %}

                {% if receiving_applicable %}
                  {% if (row.receiving_mode or "Single Unit") == "Single Unit" and frappe.utils.flt(row.receiving_capacity_qty or 0) > 0 %}
                    {% set receiving_capacity_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
                    {% set receiving_raw = required_qty / receiving_capacity_qty %}
                    {% set receiving_int = receiving_raw|int %}
                    {% set receiving_decimal = receiving_raw - receiving_int %}
                    {% set selected_rounding = row.receiving_rounding_method or "Round Up" %}

                    {% if receiving_raw > receiving_int %}
                      {% set round_up_qty = receiving_int + 1 %}
                    {% else %}
                      {% set round_up_qty = receiving_int %}
                    {% endif %}

                    {% set round_down_qty = receiving_int %}

                    {% if receiving_decimal >= 0.5 %}
                      {% set half_round_qty = receiving_int + 1 %}
                    {% else %}
                      {% set half_round_qty = receiving_int %}
                    {% endif %}

                    {% set no_rounding_qty = receiving_raw %}

                    <div class="cd-receiving-box">
                      <div class="cd-calc-line">
                        Receiving Raw =
                        Required Qty ÷ Receiving Capacity Qty =
                        {{ fmt(required_qty) }} {{ row.uom }}
                        ÷
                        {{ fmt(receiving_capacity_qty) }} {{ row.uom }} per {{ row.receiving_capacity_uom }}
                        =
                        <strong>{{ fmt(receiving_raw) }} {{ row.receiving_capacity_uom }}</strong>
                      </div>

                      <div class="cd-calc-line">
                        Selected Rounding =
                        <strong>{{ selected_rounding }}</strong>
                      </div>

                      <div class="cd-calc-line">
                        Receiving Qty =
                        {{ selected_rounding }}({{ fmt(receiving_raw) }})
                        =
                        <strong>{{ receiving_value(row, required_qty) }} {{ row.receiving_capacity_uom }}</strong>
                      </div>

                      {% set selected_receiving_qty = frappe.utils.flt(receiving_value(row, required_qty) or 0) %}

                      {% if row.use_full_receiving_qty %}
                        <div class="cd-calc-line cd-warning">
                          <span class="cd-icon-up">▲</span>
                          Use Full Receiving Qty = Yes
                          →
                          Production Qty uses full receiving covered qty:
                          <strong>{{ fmt(selected_receiving_qty * receiving_capacity_qty) }} {{ row.uom }}</strong>
                        </div>
                      {% endif %}

                      <table class="cd-mini-table">
                        <thead>
                          <tr>
                            <th>Rounding Method</th>
                            <th>Receiving Qty</th>
                            <th>Covered Qty</th>
                            <th>Difference</th>
                          </tr>
                        </thead>

                        <tbody>
                          <tr>
                            <td>Round Up</td>
                            <td><strong>{{ fmt(round_up_qty) }} {{ row.receiving_capacity_uom }}</strong></td>
                            <td>{{ fmt(round_up_qty * receiving_capacity_qty) }} {{ row.uom }}</td>
                            <td>
                              {% set diff = (round_up_qty * receiving_capacity_qty) - required_qty %}
                              {{ diff_icon(diff, row.uom) }}
                            </td>
                          </tr>

                          <tr>
                            <td>Round Down</td>
                            <td><strong>{{ fmt(round_down_qty) }} {{ row.receiving_capacity_uom }}</strong></td>
                            <td>{{ fmt(round_down_qty * receiving_capacity_qty) }} {{ row.uom }}</td>
                            <td>
                              {% set diff = (round_down_qty * receiving_capacity_qty) - required_qty %}
                              {{ diff_icon(diff, row.uom) }}
                            </td>
                          </tr>

                          <tr>
                            <td>Half Round</td>
                            <td><strong>{{ fmt(half_round_qty) }} {{ row.receiving_capacity_uom }}</strong></td>
                            <td>{{ fmt(half_round_qty * receiving_capacity_qty) }} {{ row.uom }}</td>
                            <td>
                              {% set diff = (half_round_qty * receiving_capacity_qty) - required_qty %}
                              {{ diff_icon(diff, row.uom) }}
                            </td>
                          </tr>

                          <tr>
                            <td>No Rounding</td>
                            <td><strong>{{ fmt(no_rounding_qty) }} {{ row.receiving_capacity_uom }}</strong></td>
                            <td>{{ fmt(no_rounding_qty * receiving_capacity_qty) }} {{ row.uom }}</td>
                            <td>
                              {% set diff = (no_rounding_qty * receiving_capacity_qty) - required_qty %}
                              {{ diff_icon(diff, row.uom) }}
                            </td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  {% else %}
                    <div class="cd-calc-line">
                      Receiving =
                      <strong>{{ receiving_value(row, required_qty) }} {{ receiving_uom(row) }}</strong>
                      |
                      Selected Rounding =
                      <strong>{{ row.receiving_rounding_method or "Round Up" }}</strong>
                    </div>
                  {% endif %}
                {% else %}
                  <div class="cd-calc-line">
                    Receiving =
                    <strong>-</strong>
                    <span class="cd-muted">
                      because Include in Purchase is not checked or Receiving Mode is No Receiving.
                    </span>
                  </div>
                {% endif %}
              </div>
            {% endif %}
          {% endfor %}
        </div>
      {% endif %}

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">4) Output Qty / كمية المخرج</div>

        {% if output_ns.can %}
          {% if method == "Per Buffet" %}
            <div class="cd-calc-line">
              Output Raw =
              Buffet Qty =
              <strong>{{ fmt(buffet_qty) }} {{ output_uom }}</strong>
            </div>
          {% else %}
            <div class="cd-calc-line">
              Output Raw =
              Required Qty ÷ Capacity Qty =
              {{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}
              ÷
              {{ fmt(output_ns.capacity_qty) }} {{ output_ns.capacity_uom }}
              =
              <strong>{{ fmt(output_ns.output_raw) }} {{ output_uom }}</strong>
            </div>
          {% endif %}

          <div class="cd-calc-line">
            Output Qty =
            {{ round_text(output_rounding) }}({{ fmt(output_ns.output_raw) }})
            =
            <strong>{{ fmt(output_ns.output_qty) }} {{ output_uom }}</strong>
          </div>

          <div class="cd-calc-line">
            Actual Qty After Rounding =
            Output Qty × Capacity Qty =
            {{ fmt(output_ns.output_qty) }}
            ×
            {{ fmt(output_ns.capacity_qty) }}
            =
            <strong>{{ fmt(output_ns.actual_qty) }} {{ output_ns.required_uom }}</strong>
          </div>

          {% if qty_diff_ns.enabled %}
            {% if qty_diff_ns.status == "Extra" %}
              <div class="cd-calc-line cd-warning">
                <span class="cd-icon-up">▲</span>
                Qty Difference =
                Actual Qty - Required Qty =
                {{ fmt(output_ns.actual_qty) }}
                -
                {{ fmt(output_ns.required_qty) }}
                =
                <strong>{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</strong>
              </div>
            {% elif qty_diff_ns.status == "Shortage" %}
              <div class="cd-calc-line cd-danger">
                <span class="cd-icon-down">▼</span>
                Qty Difference =
                Required Qty - Actual Qty =
                {{ fmt(output_ns.required_qty) }}
                -
                {{ fmt(output_ns.actual_qty) }}
                =
                <strong>{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</strong>
              </div>
            {% else %}
              <div class="cd-calc-line cd-success">
                <span class="cd-icon-ok">✓</span>
                Output Qty Difference =
                <strong>Exact / بدون فائض أو نقص</strong>
              </div>
            {% endif %}
          {% endif %}
        {% else %}
          <div class="cd-calc-line cd-danger">
            {{ output_ns.message }}
          </div>
        {% endif %}
      </div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">5) Runs / مرات التشغيل</div>

        {% if run_ns.can %}
          <div class="cd-calc-line">
            Equipment / Workstation =
            <strong>{{ doc.default_workstation or "" }}</strong>
          </div>

          <div class="cd-calc-line">
            Run Calculation Base =
            <strong>{{ workstation_method }}</strong>
          </div>

          <div class="cd-calc-line">
            Run Load Qty =
            <strong>{{ fmt(workstation_load_qty) }} {{ workstation_load_uom }}</strong>
          </div>

          <div class="cd-calc-line">
            Runs Raw =
            {{ run_ns.formula }}
            =
            {{ fmt(run_ns.base_qty) }}
            ÷
            {{ fmt(workstation_load_qty) }}
            =
            <strong>{{ fmt(run_ns.raw) }}</strong>
          </div>

          <div class="cd-calc-line">
            Runs =
            Round Up({{ fmt(run_ns.raw) }})
            =
            <strong>{{ fmt(run_ns.qty) }}</strong>
          </div>
        {% else %}
          <div class="cd-calc-line cd-danger">
            Runs cannot be calculated because Run Load Qty is missing or output is not calculated.
          </div>
        {% endif %}
      </div>
    </div>

    <table class="cd-table cd-output-table">
      <thead>
        <tr>
          <th>
            <div class="bi-head">
              <div class="en">Production Item</div>
              <div class="ar">الصنف المنتج</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Output Qty</div>
              <div class="ar">كمية المخرج</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Output UOM</div>
              <div class="ar">وحدة المخرج</div>
            </div>
          </th>

          {% if qty_diff_ns.enabled %}
            <th>
              <div class="bi-head">
                <div class="en">Qty Difference</div>
                <div class="ar">فرق الكمية</div>
              </div>
            </th>
          {% endif %}
        </tr>
      </thead>

      <tbody>
        <tr>
          <td class="item-col">
            <div>{{ doc.item_name or doc.dish_name }}</div>

            {% if doc.item_name_arabic or doc.dish_name_arabic %}
              <div class="item-name-ar">{{ doc.item_name_arabic or doc.dish_name_arabic }}</div>
            {% endif %}

            {% if doc.item_code %}
              <div class="cd-small">{{ doc.item_code }}</div>
            {% endif %}
          </td>

          <td>
            <span class="cd-output-number">
              {% if output_ns.can %}
                {{ fmt(output_ns.output_qty) }}
              {% else %}
                -
              {% endif %}
            </span>
          </td>

          <td>
            <span class="cd-output-uom">{{ output_uom }}</span>
          </td>

          {% if qty_diff_ns.enabled %}
            <td>
              {% if qty_diff_ns.status == "Extra" %}
                <span class="cd-icon-up">▲</span>
                <span class="cd-coverage-warning">{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</span>
              {% elif qty_diff_ns.status == "Shortage" %}
                <span class="cd-icon-down">▼</span>
                <span class="cd-coverage-danger">{{ fmt(qty_diff_ns.diff) }} {{ output_ns.required_uom }}</span>
              {% else %}
                <span class="cd-icon-ok">✓</span>
                <span class="cd-coverage-success">Exact</span>
              {% endif %}
            </td>
          {% endif %}
        </tr>
      </tbody>
    </table>

    <div class="cd-calc-block cd-dish-output-options">
      <div class="cd-calc-title">Dish Output Options / شرح خيارات الصنف الرئيسي</div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">A) Output Planning Method / طريقة حساب المخرج</div>

        <div class="cd-calc-line">
          Current Selection =
          <strong>{{ method }}</strong>
        </div>

        <div class="cd-calc-line">
          Current Result =
          <strong>{{ fmt(output_ns.output_qty) }} {{ output_uom }}</strong>
        </div>

        <table class="cd-mini-table">
          <thead>
            <tr>
              <th>Option</th>
              <th>How It Calculates</th>
              <th>Example Using Current Numbers</th>
            </tr>
          </thead>

          <tbody>
            <tr>
              <td>Dish Qty Per Person</td>
              <td>Person Qty × Qty Per Person ÷ Output Capacity</td>
              <td>
                {{ fmt(person_qty) }}
                ×
                {{ fmt(basis_qty) }}
                ÷
                {{ fmt(output_ns.capacity_qty) }}
                =
                {{ fmt(output_ns.output_raw) }}
                {{ output_uom }}
              </td>
            </tr>

            <tr>
              <td>Covers Persons</td>
              <td>Person Qty ÷ Persons Covered by One Output</td>
              <td>
                {{ fmt(person_qty) }}
                ÷
                {{ fmt(basis_qty) }}
                =
                {% if basis_qty > 0 %}
                  {{ fmt(person_qty / basis_qty) }}
                {% else %}
                  -
                {% endif %}
                {{ output_uom }}
              </td>
            </tr>

            <tr>
              <td>Output Driver Material</td>
              <td>Driver Required Qty ÷ Qty Per Output</td>
              <td>
                {{ fmt(output_ns.required_qty) }}
                ÷
                {{ fmt(output_ns.capacity_qty) }}
                =
                {{ fmt(output_ns.output_raw) }}
                {{ output_uom }}
              </td>
            </tr>

            <tr>
              <td>Sum Output Materials</td>
              <td>Sum selected output materials ÷ Output Capacity</td>
              <td>
                {{ fmt(output_ns.required_qty) }}
                ÷
                {{ fmt(output_ns.capacity_qty) }}
                =
                {{ fmt(output_ns.output_raw) }}
                {{ output_uom }}
              </td>
            </tr>

            <tr>
              <td>Per Buffet</td>
              <td>Output Qty = Buffet Qty</td>
              <td>
                {{ fmt(buffet_qty) }} {{ output_uom }}
              </td>
            </tr>

            <tr>
              <td>Manual</td>
              <td>No automatic calculation</td>
              <td>-</td>
            </tr>
          </tbody>
        </table>
      </div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">B) Receiving Display Method / طريقة عرض الاستلام للصنف الرئيسي</div>

        <div class="cd-calc-line">
          Current Selection =
          <strong>{{ receiving_display_method }}</strong>
        </div>

        <table class="cd-mini-table">
          <thead>
            <tr>
              <th>Option</th>
              <th>Receiving Value Shown</th>
              <th>Meaning</th>
            </tr>
          </thead>

          <tbody>
            <tr>
              <td>Required Qty</td>
              <td>
                <strong>{{ fmt(output_ns.required_qty) }} {{ output_ns.required_uom }}</strong>
              </td>
              <td>Show the exact required quantity before output rounding.</td>
            </tr>

            <tr>
              <td>Output Qty</td>
              <td>
                <strong>{{ fmt(output_ns.output_qty) }} {{ output_uom }}</strong>
              </td>
              <td>Show the rounded output quantity.</td>
            </tr>

            <tr>
              <td>No Receiving</td>
              <td>
                <strong>-</strong>
              </td>
              <td>No receiving value will be shown.</td>
            </tr>
          </tbody>
        </table>
      </div>

      {% if output_ns.can %}
        <div class="cd-calc-section">
          <div class="cd-calc-section-title">C) Output Rounding Method / تأثير التقريب على المخرج</div>

          {% set up_qty = output_ns.full_output_qty %}
          {% if output_ns.output_raw > output_ns.full_output_qty %}
            {% set up_qty = output_ns.full_output_qty + 1 %}
          {% endif %}

          {% set down_qty = output_ns.full_output_qty %}

          {% set half_qty = output_ns.full_output_qty %}
          {% if (output_ns.output_raw - output_ns.full_output_qty) >= 0.5 %}
            {% set half_qty = output_ns.full_output_qty + 1 %}
          {% endif %}

          {% set no_round_qty = output_ns.output_raw %}

          <table class="cd-mini-table">
            <thead>
              <tr>
                <th>Method</th>
                <th>Output Qty</th>
                <th>Actual Qty</th>
                <th>Difference</th>
              </tr>
            </thead>

            <tbody>
              <tr>
                <td>Round Up</td>
                <td><strong>{{ fmt(up_qty) }} {{ output_uom }}</strong></td>
                <td>{{ fmt(up_qty * output_ns.capacity_qty) }} {{ output_ns.required_uom }}</td>
                <td>
                  {% set diff = (up_qty * output_ns.capacity_qty) - output_ns.required_qty %}
                  {{ diff_icon(diff, output_ns.required_uom) }}
                </td>
              </tr>

              <tr>
                <td>Round Down</td>
                <td><strong>{{ fmt(down_qty) }} {{ output_uom }}</strong></td>
                <td>{{ fmt(down_qty * output_ns.capacity_qty) }} {{ output_ns.required_uom }}</td>
                <td>
                  {% set diff = (down_qty * output_ns.capacity_qty) - output_ns.required_qty %}
                  {{ diff_icon(diff, output_ns.required_uom) }}
                </td>
              </tr>

              <tr>
                <td>Half Round</td>
                <td><strong>{{ fmt(half_qty) }} {{ output_uom }}</strong></td>
                <td>{{ fmt(half_qty * output_ns.capacity_qty) }} {{ output_ns.required_uom }}</td>
                <td>
                  {% set diff = (half_qty * output_ns.capacity_qty) - output_ns.required_qty %}
                  {{ diff_icon(diff, output_ns.required_uom) }}
                </td>
              </tr>

              <tr>
                <td>No Rounding</td>
                <td><strong>{{ fmt(no_round_qty) }} {{ output_uom }}</strong></td>
                <td>{{ fmt(no_round_qty * output_ns.capacity_qty) }} {{ output_ns.required_uom }}</td>
                <td>
                  {% set diff = (no_round_qty * output_ns.capacity_qty) - output_ns.required_qty %}
                  {{ diff_icon(diff, output_ns.required_uom) }}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      {% endif %}

      {% if workstation_load_qty > 0 and output_ns.can %}
        <div class="cd-calc-section">
          <div class="cd-calc-section-title">D) Run Calculation Base / تأثير أساس حساب التشغيل</div>

          {% set output_run_raw = output_ns.output_qty / workstation_load_qty %}
          {% set output_run_int = output_run_raw|int %}

          {% if output_run_raw > output_run_int %}
            {% set output_run_qty = output_run_int + 1 %}
          {% else %}
            {% set output_run_qty = output_run_int %}
          {% endif %}

          {% if output_run_qty <= 0 and output_ns.output_qty > 0 %}
            {% set output_run_qty = 1 %}
          {% endif %}

          {% set direct_run_raw = output_ns.required_qty / workstation_load_qty %}
          {% set direct_run_int = direct_run_raw|int %}

          {% if direct_run_raw > direct_run_int %}
            {% set direct_run_qty = direct_run_int + 1 %}
          {% else %}
            {% set direct_run_qty = direct_run_int %}
          {% endif %}

          {% if direct_run_qty <= 0 and output_ns.required_qty > 0 %}
            {% set direct_run_qty = 1 %}
          {% endif %}

          <table class="cd-mini-table">
            <thead>
              <tr>
                <th>Run Calculation Base</th>
                <th>Formula</th>
                <th>Runs Raw</th>
                <th>Runs</th>
              </tr>
            </thead>

            <tbody>
              <tr>
                <td>Output Unit Load</td>
                <td>{{ fmt(output_ns.output_qty) }} ÷ {{ fmt(workstation_load_qty) }}</td>
                <td>{{ fmt(output_run_raw) }}</td>
                <td><strong>{{ fmt(output_run_qty) }}</strong></td>
              </tr>

              <tr>
                <td>Direct Quantity Load</td>
                <td>{{ fmt(output_ns.required_qty) }} ÷ {{ fmt(workstation_load_qty) }}</td>
                <td>{{ fmt(direct_run_raw) }}</td>
                <td><strong>{{ fmt(direct_run_qty) }}</strong></td>
              </tr>
            </tbody>
          </table>
        </div>
      {% endif %}
    </div>
  </div>
</div>
